let feeState=null, feeReceivedAt=0;
function renderFeeNotice(){
 const visible=!!me&&!!feeState&&Number(feeState.pendingAmount)>0;
 $('feeNotice').hidden=!visible;
 if(!visible){$('payFees').disabled=true;return}
 const hold=feeState.hold;
 $('feeNotice').classList.toggle('fee-hold',hold);
 text('feeNoticeTitle',t(hold?'feeHoldTitle':'feeTitle'));
 text('feeNoticeAmount',num(feeState.pendingAmount,6)+' USDC');
 text('feeNoticeBody',t(hold?'feeHoldBody':'feeNoticeBody'));
 const serverNow=feeState.serverTime+(performance.now()-feeReceivedAt);
 const seconds=Math.max(0,Math.ceil((feeState.deadlineAt-serverNow)/1000));
 const hours=Math.floor(seconds/3600),minutes=Math.floor((seconds%3600)/60);
 const remaining=hours+' h '+String(minutes).padStart(2,'0')+' min';
 text('feeNoticeDeadline',hold?'':seconds>0?t('feeDeadline').replace('{date}',stamp(feeState.deadlineAt)).replace('{time}',remaining):t('feeDueNow'));
 $('payFeesNotice').disabled=hold;
 $('payFees').disabled=hold;
}
function clearPrivateState(){
 me=null;feeState=null;renderUser();renderFeeNotice();
 $('tradeRows').replaceChildren();text('username','');text('walletLabel','');text('agentStatus','');
 $('privateNotice').hidden=true;
 for(const id of ['actionDialog','consentDialog'])if($(id).open)$(id).close();
}
setInterval(renderFeeNotice,30000);

let lang=localStorage.getItem('cryptoloveLanguage')||'en',me=null,settings={},history=null,filtered=[],position=0,playing=false,timer=null,signupMode=false,live=null,backtest=null,backtestMessageKey=null;
if(!dictionaries[lang])lang='en';
const t=k=>dictionaries[lang][k]??dictionaries.en[k]??k;
const num=(n,d=2)=>Number(n).toLocaleString(lang,{maximumFractionDigits:d,minimumFractionDigits:d});
const stamp=x=>CryptoLoveBacktest.stamp(x);
const pair=x=>CryptoLoveBacktest.pair(x);
const text=(id,value)=>{$(id).textContent=value};
function applyLanguage(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('.flag').forEach(el=>{el.classList.toggle('selected',el.dataset.lang===lang);el.setAttribute('aria-pressed',String(el.dataset.lang===lang))});setMode(signupMode);renderUser();renderLive();renderFeeNotice();if(backtest){renderReplay();renderHistory();renderBacktestMessage()}if(settings.feeBasis==='margin'){text('feeExplanation',t('feeMargin'));document.querySelector('[data-i18n="consentFee"]').textContent=t('feeMargin')}}
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;localStorage.setItem('cryptoloveLanguage',lang);applyLanguage();if(me)loadTrades()});
function toast(s){text('toast',s);$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6500)}
function action(fn){return async function(e){e?.preventDefault?.();const btn=e?.currentTarget;try{if(btn?.tagName==='BUTTON')btn.disabled=true;await fn(e)}catch(err){toast(err.code===4001?'MetaMask: '+(lang==='es'?'firma cancelada':'signature cancelled'):err.message||t('error'))}finally{if(btn?.tagName==='BUTTON')btn.disabled=false}}}
const apiBase=()=>{const url=window.CRYPTOLOVE?.apiUrl||'';if(!url.startsWith('https://')||url.includes('.example'))throw Error(t('apiMissing'));return url.replace(/\/$/,'')};
async function api(path,body){const res=await fetch(apiBase()+path,{method:body===undefined?'GET':'POST',credentials:'include',headers:body===undefined?{}:{'Content-Type':'application/json','X-CryptoLove':'1'},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok){if(res.status===401&&me){clearPrivateState();toast(t('feeDeleted'))}const detail=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail);throw Error(detail||t('error'))}return data}
function setMode(mode){signupMode=mode;text('authTitle',t(mode?'join':'welcome'));text('authSubmit',t(mode?'signUp':'signIn'));$('signupTab').classList.toggle('selected',mode);$('loginTab').classList.toggle('selected',!mode);$('passwordHint').hidden=!mode;$('authForm').elements.username.required=mode;$('authForm').elements.password.minLength=mode?12:1;$('authForm').elements.password.autocomplete=mode?'new-password':'current-password'}
$('loginTab').onclick=()=>setMode(false);$('signupTab').onclick=()=>setMode(true);
$('authButton').onclick=()=>{$('authMessage').textContent='';$('authDialog').showModal()};
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
async function refreshMe(){me=await api('/me');renderUser();await loadTrades()}
function renderUser(){const logged=!!me;$('authButton').hidden=logged;$('privateButton').hidden=!logged;$('private').hidden=!logged;if(!logged)return;text('username',me.username);text('walletLabel',me.wallet||t('unlinked'));text('agentStatus',(me.agent_address?(me.active?t('active'):t('paused')):t('unlinked'))+(settings.tradingEnabled?'':' · '+t('globalPause')));$('authorizeButton').hidden=!!me.agent_address;$('pauseButton').hidden=!me.agent_address;text('pauseButton',t(me.active?'pause':'resume'));$('privateNotice').hidden=!me.last_error;if(me.last_error)text('privateNotice',me.last_error)}
$('privateButton').onclick=()=>$('private').scrollIntoView({behavior:'smooth'});
$('authForm').onsubmit=action(async()=>{const form=$('authForm'),data=Object.fromEntries(new FormData(form));$('authSubmit').disabled=true;try{if(signupMode){await api('/auth/signup',data);text('authMessage',t('checkEmail'));setMode(false);form.elements.password.value=''}else{me=await api('/auth/login',data);form.reset();$('authDialog').close();await refreshMe();$('private').scrollIntoView({behavior:'smooth'})}}finally{$('authSubmit').disabled=false}});
for(const [id,path]of[['forgot','/auth/forgot'],['resend','/auth/resend']])$(id).onclick=action(async()=>{const email=$('authForm').elements.email;if(!email.reportValidity())return;await api(path,{email:email.value});text('authMessage',t('sentEmail'))});
$('logout').onclick=action(async()=>{await api('/auth/logout',{});clearPrivateState();window.scrollTo({top:0,behavior:'smooth'})});

const announced=[];window.addEventListener('eip6963:announceProvider',event=>{if(event.detail?.info?.rdns==='io.metamask')announced.push(event.detail.provider)});window.dispatchEvent(new Event('eip6963:requestProvider'));
async function metamask(){let provider=announced[0];if(!provider){window.dispatchEvent(new Event('eip6963:requestProvider'));await new Promise(r=>setTimeout(r,250));provider=announced[0]}if(!provider){const candidates=window.ethereum?.providers||[window.ethereum];provider=candidates.find(p=>p?.isMetaMask&&!p?.isBraveWallet&&!p?.isCoinbaseWallet)}if(!provider)throw Error(t('noWallet'));const accounts=await provider.request({method:'eth_requestAccounts'});if(!accounts?.[0])throw Error(t('noWallet'));return{provider,address:accounts[0]}}
async function connectWallet(){if(!me){$('authDialog').showModal();return false}const{provider,address}=await metamask();if(me.wallet&&me.wallet!==address.toLowerCase())throw Error(t('differentWallet'));const challenge=await api('/wallet/challenge',{address});const signature=await provider.request({method:'personal_sign',params:['0x'+Array.from(new TextEncoder().encode(challenge.message)).map(b=>b.toString(16).padStart(2,'0')).join(''),address]});await api('/wallet/link',{id:challenge.id,signature});await refreshMe();toast(t('connected'));return true}
$('connectButton').onclick=action(async()=>{if(await connectWallet()){$('private').scrollIntoView({behavior:'smooth'});if(!me.agent_address)openConsent()}});
function openConsent(){$('acceptConsent').checked=false;text('consentNetwork',t('network')+': Hyperliquid '+(settings.network||'testnet').toUpperCase());$('consentDialog').showModal()}
$('authorizeButton').onclick=action(async()=>{if(!me.wallet&&!await connectWallet())return;openConsent()});
async function signedRequest(prepare,commit){const{provider,address}=await metamask();if(address.toLowerCase()!==me.wallet)throw Error(t('differentWallet'));const chain=await provider.request({method:'eth_chainId'});const prepared=await api(prepare,{chain_id:chain,consent:true});return{provider,address,prepared,commit}}
async function signPrepared(x){const accounts=await x.provider.request({method:'eth_accounts'});if(accounts[0]?.toLowerCase()!==x.address.toLowerCase())throw Error(t('differentWallet'));const signature=await x.provider.request({method:'eth_signTypedData_v4',params:[x.address,JSON.stringify(x.prepared.typedData)]});return api(x.commit,{id:x.prepared.id,signature})}
$('signAgent').onclick=action(async()=>{if(!$('acceptConsent').checked)throw Error(t('agree'));const x=await signedRequest('/wallet/prepare','/wallet/authorize');await signPrepared(x);$('consentDialog').close();await refreshMe();toast(t('accepted'))});
$('pauseButton').onclick=action(async()=>{await api('/subscription',{active:!me.active});await refreshMe()});
function confirmDialog(title,body,label,fn){text('actionTitle',title);text('actionBody',body);$('resetForm').hidden=true;$('actionConfirm').hidden=false;text('actionConfirm',label);$('actionConfirm').onclick=action(async()=>{await fn();$('actionDialog').close()});$('actionDialog').showModal()}
$('payFees').onclick=action(async()=>{const x=await signedRequest('/fees/prepare','/fees/pay');confirmDialog(t('confirmPayment'),t('paymentText').replace('{amount}',x.prepared.amount).replace('{wallet}',x.prepared.destination),t('confirmPayment'),async()=>{await signPrepared(x);toast(t('paid'));await loadTrades()})});
$('payFeesNotice').onclick=()=>$('payFees').click();
$('deleteAccount').onclick=()=>confirmDialog(t('delete'),t('deleteBody'),t('delete'),async()=>{await api('/account/delete',{});clearPrivateState();toast(t('deleteDone'))});
function td(value,small){const el=document.createElement('td');el.textContent=value;if(small){const s=document.createElement('small');s.textContent=small;el.append(s)}return el}
async function loadTrades(){if(!me)return;const uid=me.id;const data=await api('/trades');if(!me||me.id!==uid)return;feeState=data.fees;feeReceivedAt=performance.now();renderFeeNotice();$('tradeRows').replaceChildren();$('emptyTrades').hidden=!!data.trades.length;for(const row of data.trades){const tr=document.createElement('tr');tr.append(td(pair(row.coin),row.side),td(stamp(row.opened)),td(row.closed?stamp(row.closed):t(row.status==='reconciling'?'reconciling':'open')),td(num(row.entry,6)),td(row.exit?num(row.exit,6):'—'));const profit=td(row.return_pct!==null?num(row.return_pct)+'%':'—');profit.classList.toggle('negative',Number(row.return_pct)<0);tr.append(profit,td(num(row.fee,6),t(row.fee_status==='paid'?'feePaid':row.fee_status==='pending'?'feePending':'feeNone')),td(row.balance?num(row.balance):'—',row.balance_at?stamp(row.balance_at):''));$('tradeRows').append(tr)}$('privateNotice').hidden=!me.last_error;if(me.last_error)text('privateNotice',me.last_error);if(data.invoices.length){$('privateNotice').hidden=false;text('privateNotice',lang==='es'?'Hay un pago sin confirmar. No lo repitas; consulta con el operador.':'A payment is awaiting reconciliation. Do not repeat it; contact the operator.')}}

async function initGoogle(){if(!settings.googleClientId)return;const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=()=>{google.accounts.id.initialize({client_id:settings.googleClientId,callback:action(async response=>{const result=await api('/auth/google',{credential:response.credential});if(result.needsConfirmation){text('authMessage',t('checkEmail'));return}me=result;$('authDialog').close();await refreshMe();$('private').scrollIntoView({behavior:'smooth'})})});$('googleWrap').hidden=false;google.accounts.id.renderButton($('googleButton'),{type:'standard',theme:'outline',size:'large',width:300})};document.head.append(script)}
async function handleLink(){const hash=location.hash.slice(1);const match=hash.match(/^(verify|reset|unsubscribe)=(.+)$/);if(!match)return;const kind=match[1],token=decodeURIComponent(match[2]);window.history.replaceState(null,'',location.pathname);if(kind==='verify'){await api('/auth/verify',{token});toast(t('verifyDone'));$('authDialog').showModal()}else if(kind==='unsubscribe'){confirmDialog(t('delete'),t('deleteBody'),t('delete'),async()=>{await api('/auth/unsubscribe',{token});clearPrivateState();toast(t('deleteDone'))})}else{text('actionTitle',t('newPassword'));text('actionBody','');$('actionConfirm').hidden=true;$('resetForm').hidden=false;$('resetForm').onsubmit=action(async()=>{await api('/auth/reset',{token,password:$('resetForm').elements.password.value});$('resetForm').reset();$('actionDialog').close();toast(t('savedPassword'))});$('actionDialog').showModal()}}

function renderLive(){
 const valid=live?.returnPct!==null&&live?.returnPct!==undefined&&Number.isFinite(Number(live.returnPct));
 const percent=valid?Number(live.returnPct):null;
 $('liveReturn').replaceChildren(document.createTextNode(valid?(percent>0?'+':'')+num(percent):'—'),Object.assign(document.createElement('span'),{textContent:'%'}));
 $('liveReturn').classList.toggle('negative',valid&&percent<0);
 if(valid){
  const status=live.status==='no_trades'?t('noTrades'):t('estimated');
  text('liveStatus',(live.stale?t('stale')+' ':'')+status+(live.asOf?' · '+t('updated')+': '+stamp(live.asOf)+' UTC':''));
 }else{
  const connected=['insufficient_baseline','awaiting_next_sample'].includes(live?.status);
  text('liveStatus',t(connected?'baselineMissing':!live||live.status==='unconfigured'?'awaiting':'noData'));
 }
 if(live?.explorer&&/^https:\/\/hypurrscan\.io\/address\/0x[0-9a-f]{40}$/.test(live.explorer)){$('auditLink').hidden=false;$('auditLink').href=live.explorer}else $('auditLink').hidden=true;
 document.querySelector('.live-rule').hidden=$('auditLink').hidden;
}
async function loadLive(){try{live=await api('/public/performance');renderLive()}catch{if(live)live.stale=true;else live={status:'unavailable',returnPct:null};renderLive()}}
function renderBacktestMessage(){
 const message=$('backtestMessage');
 const pieces=[];
 if(backtestMessageKey)pieces.push(t(backtestMessageKey));
 else if(backtest){if(backtest.partial)pieces.push(t('partialHistory'));if(!filtered.length)pieces.push(t('noSelectedTrades'))}
 message.hidden=!pieces.length;message.textContent=pieces.join(' ');
 message.classList.toggle('error',!!backtestMessageKey&&backtestMessageKey!=='updatedInputs');
}
function selectHistory(){
 if(!history)return;
 try{
  const next=CryptoLoveBacktest.replay(history,{start:$('startDate').value,end:$('endDate').value,capital:$('initialCapital').value});
  stop();backtest=next;filtered=next.trades;position=filtered.length;backtestMessageKey=null;
  for(const id of ['startDate','endDate','initialCapital'])$(id).removeAttribute('aria-invalid');
  $('timeline').max=filtered.length;$('play').disabled=!filtered.length;$('timeline').disabled=!filtered.length;
  renderHistory();renderReplay();renderBacktestMessage();
 }catch(e){
  stop();backtestMessageKey=e.message;
  const id=e.message==='minCapital'||e.message==='amountTooLarge'?'initialCapital':e.message==='dateOrder'?'endDate':'startDate';
  $(id).setAttribute('aria-invalid','true');renderBacktestMessage();$(id).focus();
 }
}
function renderHistory(){
 if(!backtest)return;
 $('historyRows').replaceChildren();
 for(const r of filtered){
  const tr=document.createElement('tr');tr.append(td(pair(r.coin),r.side),td(stamp(r.open)),td(stamp(r.close)));
  for(const value of [r.priceReturnPct,r.cumulativePct]){const cell=td((value>0?'+':'')+num(value)+'%');cell.classList.toggle('negative',value<0);tr.append(cell)}
  tr.append(td(num(r.simulatedBalance)));$('historyRows').append(tr);
 }
 text('sourceInfo',filtered.length+' '+t('trades')+' · '+CryptoLoveBacktest.date(backtest.from)+' → '+CryptoLoveBacktest.date(backtest.to-1)+' · '+t('initialCapital')+': '+num(backtest.initial)+' USDC · '+t('availableHistory')+': '+stamp(backtest.availableFrom)+' → '+stamp(backtest.availableTo)+' UTC');
}
const svgNode=(tag,attrs,content)=>{const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(content!==undefined)el.textContent=content;return el};
function values(){return backtest?.balances||[100]}
function renderReplay(){if(!backtest)return;$('chartEmpty').hidden=filtered.length>0;text('chartEmpty',t('noSelectedTrades'));const data=values();const current=data[position];text('indexValue',num(current));const totalPct=(current/backtest.initial-1)*100;text('indexReturn',(totalPct>0?'+':'')+num(totalPct)+'%');$('indexReturn').classList.toggle('negative',totalPct<0);text('progress',position+' / '+filtered.length);$('timeline').value=position;const r=filtered[Math.max(0,position-1)];text('replayCoin',position&&r?pair(r.coin):'—');text('replayOpen',position&&r?stamp(r.open):'—');text('replayClose',position&&r?stamp(r.close):'—');text('replayProfit',position&&r?(r.priceReturnPct>=0?'+':'')+num(r.priceReturnPct)+'%':'—');$('replayProfit').classList.toggle('negative',position>0&&r?.priceReturnPct<0);
const log=$('scale').value==='log',transform=v=>log?Math.log10(Math.max(.01,v)):v,extent=data.map(transform),lo=Math.min(...extent),hi=Math.max(...extent),pad=Math.max((hi-lo)*.09,log?.1:1),min=lo-pad,max=hi+pad;const X=i=>64+i/Math.max(1,filtered.length)*912,Y=v=>275-(transform(v)-min)/(max-min)*235;const pts=data.slice(0,position+1).map((v,i)=>[X(i),Y(v)]);const path=pts.map(([x,y],i)=>(i?'L':'M')+x.toFixed(2)+','+y.toFixed(2)).join(' ');$('curve').setAttribute('d',path);$('area').setAttribute('d',path+` L${X(position)},275 L64,275 Z`);$('cursorDot').setAttribute('cx',X(position));$('cursorDot').setAttribute('cy',Y(current));$('grid').replaceChildren();for(let i=0;i<5;i++){const v=min+(max-min)*i/4,y=275-i/4*235,label=log?10**v:v;$('grid').append(svgNode('line',{x1:64,y1:y,x2:976,y2:y,stroke:'#e8eef8','stroke-dasharray':'3 5'}),svgNode('text',{x:53,y:y+4,'text-anchor':'end',fill:'#8298bc','font-size':'10'},Number(label).toLocaleString(lang,{notation:'compact',maximumFractionDigits:1})))}for(let i=0;i<3;i++){const n=Math.round(filtered.length*i/2),row=filtered[Math.max(0,n-1)];if(row)$('grid').append(svgNode('text',{x:X(n),y:307,'text-anchor':i===0?'start':i===2?'end':'middle',fill:'#8298bc','font-size':'10'},CryptoLoveBacktest.date(row.close)))} }
function stop(){playing=false;clearTimeout(timer);text('play','▶');$('play').setAttribute('aria-label',lang==='es'?'Reproducir':'Play')}
function tick(){if(!playing)return;if(position>=filtered.length){stop();return}position++;renderReplay();timer=setTimeout(tick,650/Number($('speed').value))}
$('play').onclick=()=>{if(!history||!filtered.length)return;if(playing){stop();return}if(position>=filtered.length)position=0;playing=true;text('play','Ⅱ');$('play').setAttribute('aria-label',lang==='es'?'Pausar':'Pause');tick()};$('restart').onclick=()=>{stop();position=0;renderReplay()};$('timeline').oninput=()=>{stop();position=Number($('timeline').value);renderReplay()};$('scale').onchange=renderReplay;$('backtestForm').onsubmit=event=>{event.preventDefault();selectHistory()};
for(const id of ['startDate','endDate','initialCapital'])$(id).addEventListener('input',()=>{stop();backtestMessageKey='updatedInputs';renderBacktestMessage()});
$('chart').addEventListener('click',event=>{if(!backtest)return;const rect=$('chart').getBoundingClientRect();position=Math.max(0,Math.min(filtered.length,Math.round(((event.clientX-rect.left)/rect.width*1000-64)/912*filtered.length)));stop();renderReplay()});
async function init(){applyLanguage();try{const r=await fetch('history.json');if(!r.ok)throw Error('history');history=await r.json();$('startDate').value=CryptoLoveBacktest.date(history.period.from);$('endDate').value=CryptoLoveBacktest.date(history.period.to);selectHistory()}catch{text('chartEmpty',lang==='es'?'No se pudo cargar history.json':'Could not load history.json')}try{settings=await api('/public/config');applyLanguage();await initGoogle();try{await refreshMe()}catch{me=null;renderUser()}await handleLink()}catch(e){if(location.hash.match(/^#(verify|reset|unsubscribe)=/))toast(e.message)}await loadLive();setInterval(()=>{loadLive();if(me)loadTrades().catch(()=>{})},60000)}init();
